		}

		return &models.Package{
			Name: fields[0],
			Version: func() string {
				switch fields[1] {
				case "0", "(none)":
					return fields[2]
				default:
					return fmt.Sprintf("%s:%s", fields[1], fields[2])
				}
			}(),
			Release: fields[3],
			Arch:    fields[4],
			Repository: func() string {
				switch repo := strings.TrimPrefix(fields[6], "@"); repo {
				case "installed":
					return "amzn2-core"
				default:
					return repo
				}
			}(),
		}, sp, nil
	default:
